// Walks cue events with a time cursor and produces a flat list of timed events.
import type { CueEvent, NonVerbal } from "../cue/spec";

/** Tunables that shape how the narration *feels*. Ear-tuned guesses; see Docs/ADR.md (ADR-010). */
export const PACING = {
  /** Silence added after every speech segment (sentence), on top of explicit [pause]s. */
  speechGap: 0.45,
  /** Seconds a non-verbal occupies on the timeline. */
  nonverbal: { breath: 0.9, sigh: 1.3, gasp: 0.6, laugh: 1.1 } satisfies Record<NonVerbal, number>,
  /** Silence after the last event before the story is considered finished. */
  tail: 0.6,
  /** Ambient ducking: gain while speech plays, ramp times, and gaps that don't re-open the bed. */
  duckGain: 0.5, // ~ -6 dB
  duckRampIn: 0.25,
  duckRampOut: 0.6,
  duckMergeGap: 1.0,
} as const;

export interface TimedEvent {
  /** Seconds from the start of the timeline. */
  at: number;
  /** Seconds the event occupies (0 for instantaneous events). */
  duration: number;
  ev: CueEvent;
  buffer?: AudioBuffer;
}

export interface Timeline {
  items: TimedEvent[];
  total: number;
}

export function schedule(events: CueEvent[], buffers: ReadonlyMap<CueEvent, AudioBuffer>): Timeline {
  const items: TimedEvent[] = [];
  let cursor = 0;

  for (const ev of events) {
    switch (ev.kind) {
      case "speech": {
        const buffer = buffers.get(ev);
        const duration = buffer?.duration ?? 0;
        items.push({ at: cursor, duration, ev, buffer });
        cursor += duration + PACING.speechGap;
        break;
      }
      case "pause":
        items.push({ at: cursor, duration: ev.seconds, ev });
        cursor += ev.seconds;
        break;
      case "nonverbal": {
        const duration = PACING.nonverbal[ev.nv];
        items.push({ at: cursor, duration, ev });
        cursor += duration;
        break;
      }
      default:
        // sfx / light / ambient / photo are stamped at the cursor and take no time
        items.push({ at: cursor, duration: 0, ev });
    }
  }
  return { items, total: cursor + PACING.tail };
}

/** Intervals during which the ambient bed should be ducked (speech spans, merged across short gaps). */
export function duckIntervals(items: TimedEvent[]): Array<[number, number]> {
  const spans = items
    .filter((i) => i.ev.kind === "speech" && i.duration > 0)
    .map((i) => [i.at, i.at + i.duration] as [number, number]);
  const out: Array<[number, number]> = [];
  for (const s of spans) {
    const last = out[out.length - 1];
    if (last && s[0] - last[1] < PACING.duckMergeGap) last[1] = s[1];
    else out.push([s[0], s[1]]);
  }
  return out;
}

// voice -> styleChain -> voiceBus -> (dry + reverb) -> master -> destination
// ambient -> ambientBus (ducked) -> master;  sfx -> sfxBus -> master
import type { Style } from "../cue/spec";
import { PACING, type TimedEvent, duckIntervals } from "./timeline";

const IR_SECONDS = 2.5;

function makeImpulseResponse(ctx: BaseAudioContext): AudioBuffer {
  const len = Math.floor(ctx.sampleRate * IR_SECONDS);
  const ir = ctx.createBuffer(2, len, ctx.sampleRate);
  const predelay = Math.floor(ctx.sampleRate * 0.02);
  for (let ch = 0; ch < 2; ch++) {
    const d = ir.getChannelData(ch);
    for (let i = predelay; i < len; i++) {
      const t = (i - predelay) / ctx.sampleRate;
      d[i] = (Math.random() * 2 - 1) * Math.exp(-t * 2.8);
    }
  }
  return ir;
}

export class AudioGraph {
  readonly master: GainNode;
  readonly voiceBus: GainNode;
  readonly ambientBus: GainNode;
  readonly sfxBus: GainNode;

  constructor(readonly ctx: AudioContext) {
    this.master = ctx.createGain();
    this.master.gain.value = 0.9;
    this.master.connect(ctx.destination);

    this.voiceBus = ctx.createGain();
    const dry = ctx.createGain();
    const wet = ctx.createGain();
    wet.gain.value = 0.22;
    const reverb = ctx.createConvolver();
    reverb.buffer = makeImpulseResponse(ctx);
    this.voiceBus.connect(dry).connect(this.master);
    this.voiceBus.connect(reverb).connect(wet).connect(this.master);

    this.ambientBus = ctx.createGain();
    this.ambientBus.connect(this.master);

    this.sfxBus = ctx.createGain();
    this.sfxBus.gain.value = 0.8;
    this.sfxBus.connect(this.master);
  }

  /** styleChain: per-style emulation (whisper/trembling/shout) is added in M5; for now all pass through. */
  connectVoice(src: AudioNode, _style: Style) {
    src.connect(this.voiceBus);
  }

  /** Lower the ambient bed while speech plays. `t0` is the absolute context time of timeline 0. */
  scheduleDucking(items: TimedEvent[], t0: number) {
    const g = this.ambientBus.gain;
    g.setValueAtTime(1, t0);
    for (const [s, e] of duckIntervals(items)) {
      const a = t0 + Math.max(0, s - PACING.duckRampIn);
      g.setValueAtTime(1, a);
      g.linearRampToValueAtTime(PACING.duckGain, t0 + s);
      g.setValueAtTime(PACING.duckGain, t0 + e);
      g.linearRampToValueAtTime(1, t0 + e + PACING.duckRampOut);
    }
  }

  dispose() {
    this.master.disconnect();
  }
}

// Procedural drone: brown noise -> low-pass (LFO on cutoff) + two detuned low oscillators.
import type { AmbientMode } from "../cue/spec";

const LEVEL = { low: 0.12, swell: 0.35, stop: 0 } satisfies Record<AmbientMode, number>;
const RAMP = { low: 1.5, swell: 4, stop: 3 } satisfies Record<AmbientMode, number>;

function brownNoise(ctx: BaseAudioContext, seconds: number): AudioBuffer {
  const buf = ctx.createBuffer(1, Math.floor(ctx.sampleRate * seconds), ctx.sampleRate);
  const d = buf.getChannelData(0);
  let last = 0;
  for (let i = 0; i < d.length; i++) {
    last = (last + 0.02 * (Math.random() * 2 - 1)) / 1.02;
    d[i] = last * 3.5;
  }
  return buf;
}

export class Ambient {
  private readonly level: GainNode;
  private readonly nodes: AudioScheduledSourceNode[] = [];
  private lastValue = 0;
  private lastTime = 0;

  constructor(
    private readonly ctx: AudioContext,
    out: AudioNode,
  ) {
    this.level = ctx.createGain();
    this.level.gain.value = 0;
    this.level.connect(out);

    const noise = ctx.createBufferSource();
    noise.buffer = brownNoise(ctx, 8);
    noise.loop = true;
    const lp = ctx.createBiquadFilter();
    lp.type = "lowpass";
    lp.frequency.value = 400;
    noise.connect(lp).connect(this.level);

    const lfo = ctx.createOscillator();
    lfo.frequency.value = 0.07;
    const lfoDepth = ctx.createGain();
    lfoDepth.gain.value = 150;
    lfo.connect(lfoDepth).connect(lp.frequency);

    const oscGain = ctx.createGain();
    oscGain.gain.value = 0.5;
    oscGain.connect(this.level);
    const a = ctx.createOscillator();
    a.type = "sine";
    a.frequency.value = 47;
    const b = ctx.createOscillator();
    b.type = "triangle";
    b.frequency.value = 53.5;
    a.connect(oscGain);
    b.connect(oscGain);

    this.nodes.push(noise, lfo, a, b);
  }

  /** Start the (silent) sources at absolute context time `t`. */
  start(t: number) {
    this.nodes.forEach((n) => n.start(t));
    this.lastTime = t;
  }

  /** Schedule a mode change at absolute time `t`. Call in time order. */
  apply(mode: AmbientMode, t: number) {
    const g = this.level.gain;
    const at = Math.max(t, this.lastTime);
    g.setValueAtTime(this.lastValue, at);
    g.linearRampToValueAtTime(LEVEL[mode], at + RAMP[mode]);
    this.lastValue = LEVEL[mode];
    this.lastTime = at + RAMP[mode];
  }

  dispose() {
    for (const n of this.nodes) {
      try {
        n.stop();
      } catch {
        /* never started */
      }
    }
    this.level.disconnect();
  }
}

// Procedural one-shot sounds. All times are absolute AudioContext times.
import type { NonVerbal, SfxName } from "../cue/spec";

const noiseCache = new WeakMap<BaseAudioContext, AudioBuffer>();
function noiseBuffer(ctx: BaseAudioContext): AudioBuffer {
  let b = noiseCache.get(ctx);
  if (!b) {
    b = ctx.createBuffer(1, ctx.sampleRate * 3, ctx.sampleRate);
    const d = b.getChannelData(0);
    for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
    noiseCache.set(ctx, b);
  }
  return b;
}

const FLOOR = 0.0001;

function envelope(ctx: BaseAudioContext, out: AudioNode, t: number, dur: number, peak: number, attack: number) {
  const g = ctx.createGain();
  g.gain.setValueAtTime(FLOOR, t);
  g.gain.linearRampToValueAtTime(peak, t + attack);
  g.gain.exponentialRampToValueAtTime(FLOOR, t + dur);
  g.connect(out);
  return g;
}

function noiseBurst(
  ctx: BaseAudioContext,
  out: AudioNode,
  t: number,
  dur: number,
  filter: BiquadFilterType,
  freq: number,
  q: number,
  peak: number,
  attack = 0.005,
  sweepTo?: number,
) {
  const src = ctx.createBufferSource();
  src.buffer = noiseBuffer(ctx);
  const f = ctx.createBiquadFilter();
  f.type = filter;
  f.frequency.setValueAtTime(freq, t);
  if (sweepTo) f.frequency.linearRampToValueAtTime(sweepTo, t + dur);
  f.Q.value = q;
  src.connect(f).connect(envelope(ctx, out, t, dur, peak, attack));
  src.start(t, Math.random() * 1.5, dur + 0.05);
}

function tone(
  ctx: BaseAudioContext,
  out: AudioNode,
  t: number,
  dur: number,
  type: OscillatorType,
  f0: number,
  f1: number,
  peak: number,
  attack = 0.005,
) {
  const o = ctx.createOscillator();
  o.type = type;
  o.frequency.setValueAtTime(f0, t);
  o.frequency.exponentialRampToValueAtTime(f1, t + dur);
  o.connect(envelope(ctx, out, t, dur, peak, attack));
  o.start(t);
  o.stop(t + dur + 0.05);
}

function creak(ctx: BaseAudioContext, out: AudioNode, t: number, dur: number, peak: number) {
  const o = ctx.createOscillator();
  o.type = "sawtooth";
  o.frequency.setValueAtTime(70, t);
  o.frequency.linearRampToValueAtTime(130, t + dur);
  const wobble = ctx.createOscillator();
  wobble.frequency.value = 9;
  const wobbleDepth = ctx.createGain();
  wobbleDepth.gain.value = 18;
  wobble.connect(wobbleDepth).connect(o.frequency);
  const bp = ctx.createBiquadFilter();
  bp.type = "bandpass";
  bp.frequency.value = 720;
  bp.Q.value = 8;
  o.connect(bp).connect(envelope(ctx, out, t, dur, peak, dur * 0.3));
  o.start(t);
  wobble.start(t);
  o.stop(t + dur + 0.05);
  wobble.stop(t + dur + 0.05);
}

type SfxFn = (ctx: BaseAudioContext, out: AudioNode, t: number) => void;

const SFX: Record<SfxName, SfxFn> = {
  heartbeat: (c, o, t) => {
    // three lub-dub cycles
    for (let i = 0; i < 3; i++) {
      const b = t + i * 0.95;
      tone(c, o, b, 0.22, "sine", 62, 38, 0.9, 0.01);
      tone(c, o, b + 0.28, 0.2, "sine", 55, 36, 0.6, 0.01);
    }
  },
  knock: (c, o, t) => {
    for (const dt of [0, 0.3, 0.55]) {
      noiseBurst(c, o, t + dt, 0.09, "lowpass", 900, 1, 0.9, 0.002);
      tone(c, o, t + dt, 0.12, "sine", 130, 70, 0.8, 0.002);
    }
  },
  creak: (c, o, t) => creak(c, o, t, 1.6, 0.35),
  footsteps: (c, o, t) => {
    for (let i = 0; i < 6; i++) {
      const s = t + i * 0.55 + (i % 2) * 0.04;
      noiseBurst(c, o, s, 0.14, "lowpass", 260, 1, i % 2 ? 0.5 : 0.7, 0.01);
      tone(c, o, s, 0.12, "sine", 90, 55, 0.4, 0.008);
    }
  },
  drip: (c, o, t) => {
    tone(c, o, t, 0.1, "sine", 1900, 700, 0.5, 0.002);
    tone(c, o, t + 1.1, 0.1, "sine", 1500, 600, 0.25, 0.002);
  },
  static: (c, o, t) => {
    for (let i = 0; i < 6; i++) noiseBurst(c, o, t + i * 0.2, 0.18, "highpass", 2500, 0.7, 0.35 * (i % 2 ? 0.6 : 1), 0.005);
  },
  scrape: (c, o, t) => noiseBurst(c, o, t, 1.3, "bandpass", 350, 3, 0.5, 0.25, 1400),
  door: (c, o, t) => {
    creak(c, o, t, 0.9, 0.3);
    tone(c, o, t + 0.85, 0.3, "sine", 85, 40, 0.9, 0.005);
    noiseBurst(c, o, t + 0.85, 0.2, "lowpass", 500, 1, 0.5, 0.003);
  },
  whispers: (c, o, t) => {
    const src = c.createBufferSource();
    src.buffer = noiseBuffer(c);
    const bp = c.createBiquadFilter();
    bp.type = "bandpass";
    bp.frequency.value = 2200;
    bp.Q.value = 2.5;
    const flutter = c.createGain();
    flutter.gain.value = 0.5;
    const lfo = c.createOscillator();
    lfo.frequency.value = 6.5;
    const lfoDepth = c.createGain();
    lfoDepth.gain.value = 0.4;
    lfo.connect(lfoDepth).connect(flutter.gain);
    src.connect(bp).connect(flutter).connect(envelope(c, o, t, 3.2, 0.35, 0.8));
    src.start(t, 0, 3.3);
    lfo.start(t);
    lfo.stop(t + 3.3);
  },
};

const NONVERBAL: Record<NonVerbal, SfxFn> = {
  breath: (c, o, t) => noiseBurst(c, o, t, 0.8, "bandpass", 1100, 0.8, 0.35, 0.3),
  sigh: (c, o, t) => noiseBurst(c, o, t, 1.2, "bandpass", 800, 0.7, 0.4, 0.25, 400),
  gasp: (c, o, t) => noiseBurst(c, o, t, 0.5, "bandpass", 1600, 0.9, 0.6, 0.12, 2400),
  laugh: (c, o, t) => {
    for (let i = 0; i < 4; i++) noiseBurst(c, o, t + i * 0.22, 0.14, "bandpass", 900, 1.2, 0.3, 0.02);
  },
};

export function playSfx(name: SfxName, ctx: BaseAudioContext, out: AudioNode, t: number) {
  SFX[name](ctx, out, t);
}

export function playNonverbal(nv: NonVerbal, ctx: BaseAudioContext, out: AudioNode, t: number) {
  NONVERBAL[nv](ctx, out, t);
}

// CSS overlay effects over the Stage, driven by the timeline clock (so Pause freezes them).
import type { LightMode } from "../cue/spec";

export interface EffectElements {
  black: HTMLElement;
  red: HTMLElement;
  vignette: HTMLElement;
}

interface Active {
  mode: "flicker" | "blackout" | "red";
  start: number;
  dur: number;
  /** flicker: per-step opacities */
  steps?: number[];
  hold?: number;
}

const FLICKER_STEP = 0.07;
const clamp01 = (n: number) => Math.min(1, Math.max(0, n));

/** 0→1 over `fin`, hold, 1→0 over the last `fout` seconds of `dur`. */
function trapezoid(t: number, dur: number, fin: number, fout: number) {
  if (t < 0 || t > dur) return 0;
  return Math.min(clamp01(t / fin), clamp01((dur - t) / fout));
}

export class Effects {
  private active: Active[] = [];
  private pulseStart: number | null = null;

  /** `reduce()` is read live, so the toggle takes effect immediately. */
  constructor(
    private readonly els: EffectElements,
    private readonly reduce: () => boolean,
  ) {}

  /** `now` is timeline seconds. */
  trigger(mode: LightMode, seconds: number | undefined, now: number) {
    const reduce = this.reduce();
    switch (mode) {
      case "flicker": {
        if (reduce) {
          this.active.push({ mode: "flicker", start: now, dur: 2.5 }); // slow dim
        } else {
          const dur = 0.6 + Math.random() * 0.9;
          const steps = Array.from({ length: Math.ceil(dur / FLICKER_STEP) }, () =>
            Math.random() < 0.55 ? 0.35 + Math.random() * 0.6 : 0,
          );
          this.active.push({ mode: "flicker", start: now, dur, steps });
        }
        break;
      }
      case "blackout": {
        const hold = seconds ?? 2;
        // reduce: dim (not black) with 1.5 s fades in and out
        this.active.push({ mode: "blackout", start: now, dur: reduce ? hold + 3 : hold, hold });
        break;
      }
      case "red":
        this.active.push({ mode: "red", start: now, dur: 6 });
        break;
      case "pulse":
        this.pulseStart = now;
        break;
      case "calm":
        this.clear();
        break;
    }
  }

  update(now: number) {
    const reduce = this.reduce();
    let black = 0;
    let red = 0;

    this.active = this.active.filter((a) => now - a.start <= a.dur);
    for (const a of this.active) {
      const t = now - a.start;
      if (a.mode === "flicker") {
        if (a.steps) black = Math.max(black, a.steps[Math.floor(t / FLICKER_STEP)] ?? 0);
        else black = Math.max(black, 0.45 * Math.sin(Math.PI * clamp01(t / a.dur)));
      } else if (a.mode === "blackout") {
        const env = reduce ? trapezoid(t, a.dur, 1.5, 1.5) : trapezoid(t, a.dur, 0.12, 0.8);
        black = Math.max(black, (reduce ? 0.85 : 0.97) * env);
      } else {
        red = Math.max(red, 0.85 * trapezoid(t, a.dur, 1.5, 1.5));
      }
    }

    const vignette = this.pulseStart === null ? 0 : 0.35 + 0.25 * Math.sin(((now - this.pulseStart) * 2 * Math.PI) / 1.2);

    this.els.black.style.opacity = String(black);
    this.els.red.style.opacity = String(red);
    this.els.vignette.style.opacity = String(vignette);
  }

  clear() {
    this.active = [];
    this.pulseStart = null;
    this.els.black.style.opacity = "0";
    this.els.red.style.opacity = "0";
    this.els.vignette.style.opacity = "0";
  }
}

// Prerender -> schedule -> play. Audio is scheduled against AudioContext.currentTime;
// visual/transcript events are dispatched from a rAF loop reading the same clock.
import type { CueEvent, Style } from "../cue/spec";
import type { TTSAdapter } from "../adapters/tts/types";
import { timing } from "../lib/timing";
import { AudioGraph } from "./audioGraph";
import { Ambient } from "./ambient";
import { playNonverbal, playSfx } from "./sfx";
import { schedule, type Timeline } from "./timeline";

export interface Prepared {
  events: CueEvent[];
  timeline: Timeline;
}

export interface PrepareOptions {
  adapter: TTSAdapter;
  voice: string;
  signal?: AbortSignal;
  onProgress?: (done: number, total: number) => void;
}

export interface PlayerHooks {
  onLine?(text: string, style: Style): void;
  /** Non-audio timeline events: light, photo. `at` is timeline seconds. */
  onVisual?(ev: Extract<CueEvent, { kind: "light" | "photo" }>, at: number): void;
  /** Called every frame with timeline seconds. */
  onFrame?(elapsed: number): void;
  onEnd?(reason: "finished" | "stopped"): void;
}

export type PlayerState = "idle" | "playing" | "paused";

/** Synthesize all speech (Kokoro concurrency 1) and compute the timeline. */
export async function prepare(events: CueEvent[], o: PrepareOptions): Promise<Prepared> {
  const speech = events.filter((e): e is Extract<CueEvent, { kind: "speech" }> => e.kind === "speech");
  const buffers = new Map<CueEvent, AudioBuffer>();
  const stop = timing.start("prerender total");
  o.onProgress?.(0, speech.length);
  for (const ev of speech) {
    buffers.set(ev, await o.adapter.synth({ text: ev.text, style: ev.style, voice: o.voice }, o.signal));
    o.onProgress?.(buffers.size, speech.length);
  }
  stop();
  return { events, timeline: schedule(events, buffers) };
}

const LEAD_IN = 0.3;

export class Player {
  state: PlayerState = "idle";

  private graph: AudioGraph | null = null;
  private ambient: Ambient | null = null;
  private speechSources: AudioBufferSourceNode[] = [];
  private raf = 0;
  private t0 = 0;
  private next = 0;
  private prepared: Prepared | null = null;
  private hooks: PlayerHooks = {};

  constructor(private readonly ctx: AudioContext) {}

  /** Start (or replay) a prepared story. No re-synthesis. */
  async start(p: Prepared, hooks: PlayerHooks = {}) {
    this.teardown();
    this.prepared = p;
    this.hooks = hooks;
    if (this.ctx.state !== "running") await this.ctx.resume();

    const ctx = this.ctx;
    const graph = (this.graph = new AudioGraph(ctx));
    const ambient = (this.ambient = new Ambient(ctx, graph.ambientBus));
    const t0 = (this.t0 = ctx.currentTime + LEAD_IN);
    ambient.start(t0);
    graph.scheduleDucking(p.timeline.items, t0);

    for (const { at, ev, buffer } of p.timeline.items) {
      const t = t0 + at;
      switch (ev.kind) {
        case "speech": {
          if (!buffer) break;
          const src = ctx.createBufferSource();
          src.buffer = buffer;
          graph.connectVoice(src, ev.style);
          src.start(t);
          this.speechSources.push(src);
          break;
        }
        case "sfx":
          playSfx(ev.name, ctx, graph.sfxBus, t);
          break;
        case "nonverbal":
          playNonverbal(ev.nv, ctx, graph.sfxBus, t);
          break;
        case "ambient":
          ambient.apply(ev.mode, t);
          break;
        default:
          break; // pause, light, photo: no audio
      }
    }

    this.next = 0;
    this.state = "playing";
    const loop = () => {
      this.raf = requestAnimationFrame(loop);
      this.tick();
    };
    loop();
  }

  private tick() {
    const p = this.prepared;
    if (!p) return;
    const elapsed = this.ctx.currentTime - this.t0;
    const items = p.timeline.items;
    while (this.next < items.length && items[this.next].at <= elapsed) {
      const { at, ev } = items[this.next++];
      if (ev.kind === "speech") this.hooks.onLine?.(ev.text, ev.style);
      else if (ev.kind === "light" || ev.kind === "photo") this.hooks.onVisual?.(ev, at);
    }
    this.hooks.onFrame?.(Math.max(0, elapsed));
    if (elapsed >= p.timeline.total) this.finish("finished");
  }

  async pause() {
    if (this.state !== "playing") return;
    this.state = "paused";
    await this.ctx.suspend();
  }

  async resume() {
    if (this.state !== "paused") return;
    this.state = "playing";
    await this.ctx.resume();
  }

  async toggle() {
    if (this.state === "playing") await this.pause();
    else if (this.state === "paused") await this.resume();
  }

  stop() {
    if (this.state === "idle") return;
    this.finish("stopped");
  }

  private finish(reason: "finished" | "stopped") {
    const hooks = this.hooks;
    this.teardown();
    if (this.ctx.state === "suspended") void this.ctx.resume();
    hooks.onEnd?.(reason);
  }

  private teardown() {
    cancelAnimationFrame(this.raf);
    for (const s of this.speechSources) {
      try {
        s.stop();
      } catch {
        /* not started */
      }
    }
    this.speechSources = [];
    this.ambient?.dispose();
    this.graph?.dispose();
    this.ambient = null;
    this.graph = null;
    this.state = "idle";
  }
}

import { describe, expect, it } from "vitest";
import type { CueEvent } from "../cue/spec";
import { PACING, duckIntervals, schedule } from "./timeline";

const buf = (duration: number) => ({ duration }) as AudioBuffer;
const speech = (text: string): CueEvent => ({ kind: "speech", text, style: "normal" });

describe("schedule", () => {
  it("advances by speech duration + gap, pauses, and nonverbals; stamps instants at the cursor", () => {
    const a = speech("a");
    const b = speech("b");
    const events: CueEvent[] = [
      { kind: "ambient", mode: "low" },
      a,
      { kind: "pause", seconds: 2 },
      { kind: "sfx", name: "creak" },
      { kind: "nonverbal", nv: "gasp" },
      b,
    ];
    const { items, total } = schedule(events, new Map([[a, buf(1.5)], [b, buf(1)]]));
    expect(items.map((i) => [i.ev.kind, +i.at.toFixed(2)])).toEqual([
      ["ambient", 0],
      ["speech", 0],
      ["pause", 1.5 + PACING.speechGap],
      ["sfx", 1.5 + PACING.speechGap + 2],
      ["nonverbal", 1.5 + PACING.speechGap + 2],
      ["speech", 1.5 + PACING.speechGap + 2 + PACING.nonverbal.gasp],
    ].map(([k, t]) => [k, +(t as number).toFixed(2)]));
    const end = 1.5 + PACING.speechGap + 2 + PACING.nonverbal.gasp + 1 + PACING.speechGap;
    expect(total).toBeCloseTo(end + PACING.tail);
  });

  it("empty input gives an empty timeline", () => {
    expect(schedule([], new Map()).items).toEqual([]);
  });
});

describe("duckIntervals", () => {
  it("merges speech spans separated by less than the merge gap", () => {
    const a = speech("a");
    const b = speech("b");
    const c = speech("c");
    const { items } = schedule(
      [a, b, { kind: "pause", seconds: 5 }, c],
      new Map([[a, buf(1)], [b, buf(1)], [c, buf(1)]]),
    );
    const iv = duckIntervals(items);
    expect(iv).toHaveLength(2);
    expect(iv[0][0]).toBe(0);
    expect(iv[0][1]).toBeCloseTo(1 + PACING.speechGap + 1);
  });
});

